                self.emptyheight=min(.75,max(s.get(o,'y')+s.get(o,'height') for o in s.get_objects(self.ot))+.225)
                self.carryheight=min(.89,self.emptyheight+s.get(self.obj,'height')+.008)
                self.phase='above'
            x,y,w,h=self.rect(s,self.obj)
            if self.phase == 'above':
